window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1c65692b4e388f1d"]={"versions": [{"id": "FIG-1c65692b4e388f1d", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Screenshot zweier überlagerter MATLAB/Simulink-Modellfenster im Kontext des AUTOSAR-Simulink-Styleguides. Dargestellt ist die Modellierung einer AUTOSAR-Runnable (<code>Runnable_USES_EA</code>), in der nur ein Teilbereich der Funktionalität innerhalb einer Exclusive Area geschützt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das übergeordnete Modellfenster <code>AUTOSAR_Exclusive_Areas/Runnable_USES_EA</code> umfasst:</p>\n<ul class=\"fig-list\">\n<li><code>RteEvent</code>: Triggerelement zur Aktivierung der Runnable Entity.</li>\n<li><code>Inport DE_1</code>: Dateneingang der Runnable für das Datenelement <code>DE_1</code>.</li>\n<li>Subsystem <code>Some functionality within an Exclusive Area</code>: Hervorgehoben durch einen gelben Hintergrundbereich, mit Signaleingang <code>In1</code> und Signalausgang <code>Out1</code>.</li>\n<li><code>Outport DE_a</code>: Datenausgang der Runnable für das Datenelement <code>DE_a</code>.</li>\n</ul>\n<p class=\"fig-p\">Das untergeordnete Fenster zeigt das Innere des Subsystems:</p>\n<ul class=\"fig-list\">\n<li>Textblock / Annotation: <code>Exclusive Area ID=SMS</code> (Kennzeichnung der zugeordneten Exclusive Area).</li>\n<li>Hinweistext: „Note if part of runnable is within an Exclusive Area 1. Description property USES-EXCLUSIVE-AREAS is used 2. Runnable code generation is affected“.</li>\n<li>Diskrete Regelschleife bestehend aus: Inport <code>In1</code>, Summierstelle mit invertiertem Rückführpfad (<code>+-</code>), diskretem Differenzbaustein <code>Difference</code> (Übertragungsfunktion <code>(z-1)/z</code>), Abgriff auf Signalzweig <code>DE_a</code> zur Rückführung und Weiterleitung an Outport <code>Out1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein RTE-Ereignis (<code>RteEvent</code>) triggert die Ausführung der Runnable <code>Runnable_USES_EA</code>.</li>\n<li>Das Eingangssignal <code>DE_1</code> wird an das Subsystem <code>Some functionality within an Exclusive Area</code> übergeben.</li>\n<li>Vor Betreten des Subsystems bzw. des geschützten Codeabschnitts erfolgt über den RTE-Mechanismus der Eintritt in die Exclusive Area <code>SMS</code> (Aufruf von <code>Rte_Enter_SMS()</code>).</li>\n<li>Innerhalb des Subsystems wird die diskrete Berechnung mit Rückkopplung ausgeführt.</li>\n<li>Nach Verlassen des geschützten Abschnitts wird die Exclusive Area verlassen (Aufruf von <code>Rte_Exit_SMS()</code>), bevor das Ergebnis an den Ausgangsport <code>DE_a</code> bereitgestellt wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Wird nur ein Teil einer Runnable Entity durch eine Exclusive Area geschützt, muss im AUTOSAR-Software-Component-Description-Modell die Eigenschaft <code>canEnterExclusiveArea</code> bzw. <code>usesExclusiveAreas</code> (im Text bezeichnet als <code>USES-EXCLUSIVE-AREAS</code>) für die Runnable konfiguriert werden.</li>\n<li>Dies unterscheidet sich vom Schutz einer vollständigen Runnable (<code>runsInsideExclusiveArea</code>), da hier im generierten C-Code explizite API-Aufrufe (<code>Rte_Enter_&lt;name&gt;()</code> und <code>Rte_Exit_&lt;name&gt;()</code>) um den geschützten Funktionsabschnitt erzeugt werden müssen.</li>\n<li>Modellierer müssen sicherstellen, dass die im Subsystem referenzierte Kennung (<code>Exclusive Area ID=SMS</code>) mit der im AUTOSAR-Authoring-Tool deklarierten Exclusive Area übereinstimmt.</li>\n</ul>"}, {"id": "FIG-90d79d3784767f7d", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Screenshot zweier überlagerter MATLAB/Simulink-Modellfenster im Kontext des AUTOSAR-Simulink-Styleguides. Dargestellt ist die Modellierung einer AUTOSAR-Runnable (<code>Runnable_USES_EA</code>), in der nur ein Teilbereich der Funktionalität innerhalb einer Exclusive Area geschützt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das übergeordnete Modellfenster <code>AUTOSAR_Exclusive_Areas/Runnable_USES_EA</code> umfasst:</p>\n<ul class=\"fig-list\">\n<li><code>RteEvent</code>: Triggerelement zur Aktivierung der Runnable Entity.</li>\n<li><code>Inport DE_1</code>: Dateneingang der Runnable für das Datenelement <code>DE_1</code>.</li>\n<li>Subsystem <code>Some functionality within an Exclusive Area</code>: Hervorgehoben durch einen gelben Hintergrundbereich, mit Signaleingang <code>In1</code> und Signalausgang <code>Out1</code>.</li>\n<li><code>Outport DE_a</code>: Datenausgang der Runnable für das Datenelement <code>DE_a</code>.</li>\n</ul>\n<p class=\"fig-p\">Das untergeordnete Fenster zeigt das Innere des Subsystems:</p>\n<ul class=\"fig-list\">\n<li>Textblock / Annotation: <code>Exclusive Area ID=SMS</code> (Kennzeichnung der zugeordneten Exclusive Area).</li>\n<li>Hinweistext: „Note if part of runnable is within an Exclusive Area 1. Description property USES-EXCLUSIVE-AREAS is used 2. Runnable code generation is affected“.</li>\n<li>Diskrete Regelschleife bestehend aus: Inport <code>In1</code>, Summierstelle mit invertiertem Rückführpfad (<code>+-</code>), diskretem Differenzbaustein <code>Difference</code> (Übertragungsfunktion <code>(z-1)/z</code>), Abgriff auf Signalzweig <code>DE_a</code> zur Rückführung und Weiterleitung an Outport <code>Out1</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ein RTE-Ereignis (<code>RteEvent</code>) triggert die Ausführung der Runnable <code>Runnable_USES_EA</code>.</li>\n<li>Das Eingangssignal <code>DE_1</code> wird an das Subsystem <code>Some functionality within an Exclusive Area</code> übergeben.</li>\n<li>Vor Betreten des Subsystems bzw. des geschützten Codeabschnitts erfolgt über den RTE-Mechanismus der Eintritt in die Exclusive Area <code>SMS</code> (Aufruf von <code>Rte_Enter_SMS()</code>).</li>\n<li>Innerhalb des Subsystems wird die diskrete Berechnung mit Rückkopplung ausgeführt.</li>\n<li>Nach Verlassen des geschützten Abschnitts wird die Exclusive Area verlassen (Aufruf von <code>Rte_Exit_SMS()</code>), bevor das Ergebnis an den Ausgangsport <code>DE_a</code> bereitgestellt wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Wird nur ein Teil einer Runnable Entity durch eine Exclusive Area geschützt, muss im AUTOSAR-Software-Component-Description-Modell die Eigenschaft <code>canEnterExclusiveArea</code> bzw. <code>usesExclusiveAreas</code> (im Text bezeichnet als <code>USES-EXCLUSIVE-AREAS</code>) für die Runnable konfiguriert werden.</li>\n<li>Dies unterscheidet sich vom Schutz einer vollständigen Runnable (<code>runsInsideExclusiveArea</code>), da hier im generierten C-Code explizite API-Aufrufe (<code>Rte_Enter_&lt;name&gt;()</code> und <code>Rte_Exit_&lt;name&gt;()</code>) um den geschützten Funktionsabschnitt erzeugt werden müssen.</li>\n<li>Modellierer müssen sicherstellen, dass die im Subsystem referenzierte Kennung (<code>Exclusive Area ID=SMS</code>) mit der im AUTOSAR-Authoring-Tool deklarierten Exclusive Area übereinstimmt.</li>\n</ul>"}], "trans": [{"from": "FIG-1c65692b4e388f1d", "to": "FIG-90d79d3784767f7d", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
